// ── Conformance / structural checks ────────────────────────────────────────

Given('the app source at {string}', function (path) {
  const ROOT = path.resolve(__dirname, '..', '..');
  this.appSource = fs.readFileSync(path.resolve(ROOT, path), 'utf8');
});

When('the conformance verifier checks the {string} contract in {string}', function (contractName, schemaPath) {
  const ROOT = path.resolve(__dirname, '..', '..');
  const schema = JSON.parse(fs.readFileSync(path.resolve(ROOT, schemaPath), 'utf8'));
  this.conformanceResult = { violated: false, errors: [] };

  // Check forbidden patterns
  if (schema.forbidden) {
    for (const entry of schema.forbidden) {
      const regex = new RegExp(entry.pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
      if (regex.test(this.appSource)) {
        this.conformanceResult.violated = true;
        this.conformanceResult.errors.push('Forbidden pattern found: ' + entry.pattern + ' — ' + entry.explanation);
      }
    }
  }

  // Check required patterns
  this.conformanceResult.requiredChecks = [];
  if (schema.required) {
    for (const entry of schema.required) {
      const regex = new RegExp(entry.pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
      const found = regex.test(this.appSource);
      this.conformanceResult.requiredChecks.push({ pattern: entry.pattern, found: found, explanation: entry.explanation });
      if (!found) {
        this.conformanceResult.violated = true;
        this.conformanceResult.errors.push('Required pattern missing: ' + entry.pattern + ' — ' + entry.explanation);
      }
    }
  }
});

Then('no forbidden patterns are found', function () {
  const forbiddenViolations = this.conformanceResult.errors.filter(e => e.startsWith('Forbidden pattern'));
  assert.strictEqual(forbiddenViolations.length, 0, 'Forbidden patterns found:\n' + forbiddenViolations.join('\n'));
});

Then('all required patterns are present', function () {
  const missing = this.conformanceResult.requiredChecks.filter(c => !c.found);
  assert.strictEqual(missing.length, 0, 'Required patterns missing:\n' + missing.map(m => m.pattern + ' — ' + m.explanation).join('\n'));
});

