When('I capture the todo element reference', function () {
  const li = this.document.querySelector('.todo-list li:first-child');
  this.capturedTodoElement = li;
});

Then('the captured todo element is still attached to the DOM', function () {
  assert.ok(this.capturedTodoElement, 'No captured element reference');
  // In happy-dom, isConnected works: innerHTML replacement detaches old nodes
  assert.ok(this.capturedTodoElement.isConnected, 'Captured element is no longer in the DOM');
});

Then('the captured todo element has class {string}', function (className) {
  assert.ok(this.capturedTodoElement, 'No captured element reference');
  assert.ok(this.capturedTodoElement.classList.contains(className));
});

When('I capture all todo element references', function () {
  this.capturedTodoElements = Array.from(this.document.querySelectorAll('.todo-list li'));
});

Then('all captured todo elements are still attached to the DOM', function () {
  assert.ok(this.capturedTodoElements, 'No captured element references');
  for (const el of this.capturedTodoElements) {
    assert.ok(el.isConnected, 'A captured element is no longer in the DOM');
  }
});

Then('the edit input is visible', function () {
