function render() {
  todos = getTodos();
  var filtered = getFilteredTodos();

  // Reconcile LI elements by todo id to preserve DOM element identity.
  // Mark existing children by data-id, then reuse or create as needed.
  var existing = {};
  var children = Array.prototype.slice.call(todoList.children);
  children.forEach(function (li) {
    var id = li.getAttribute('data-id');
    if (id) existing[id] = li;
  });

  var fragment = document.createDocumentFragment();
  filtered.forEach(function (todo) {
    var li = existing[todo.id];
    if (li) {
      delete existing[todo.id];
      // Clear inner children but preserve LI element itself
      while (li.firstChild) li.removeChild(li.firstChild);
      li.className = '';
    } else {
      li = document.createElement('li');
    }
    li.setAttribute('data-id', todo.id);
    if (todo.completed) li.classList.add('completed');

    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + escapeHtml(todo.title) + '">';

    // ── Toggle ──────────────────────────────────────────────────
    li.querySelector('.toggle').addEventListener('click', function () {
      todo.completed = this.checked;
      todo.editing = false;
      setTodos(todos);
      render();
    });

    // ── Destroy ─────────────────────────────────────────────────
    li.querySelector('.destroy').addEventListener('click', function () {
      todos = todos.filter(function (t) { return t !== todo; });
      setTodos(todos);
      render();
    });

    // ── Label dblclick → edit ───────────────────────────────────
    li.querySelector('label').addEventListener('dblclick', function () {
      todo.editing = true;
      render();
      var editInput = li.querySelector('.edit');
      editInput.focus();
      editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
    });

    // ── Edit input ──────────────────────────────────────────────
    var editInput = li.querySelector('.edit');
    editInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        e.preventDefault();
        commitEdit(li, todo);
      } else if (e.keyCode === ESCAPE_KEY) {
        todo.editing = false;
        setTodos(todos);
        render();
      }
    });
    editInput.addEventListener('blur', function () {
      commitEdit(li, todo);
    });

    if (todo.editing) li.classList.add('editing');

    fragment.appendChild(li);
  });

  // Remove stale LIs that were not reused
  for (var id in existing) {
    var staleLi = existing[id];
    if (staleLi.parentNode) staleLi.parentNode.removeChild(staleLi);
  }

  todoList.appendChild(fragment);

